248	    /**
249	     * The {@link #getMemberId() memberId} with any collision-dedup suffix ({@code -<n>})
250	     * stripped, i.e. the {@code <REGION><FY><HASH8><CHK>} base whose trailing segments have
251	     * the fixed widths {@link #FY_WIDTH}/{@link #HASH8_WIDTH}/{@link #CHK_WIDTH}. Null when
252	     * no memberId is set.
