360	    /**
361	     * The fiscal year (starting 1 July) that the registration date falls in, as a
362	     * number: a date on or after 1 July belongs to the fiscal year of its own calendar
363	     * year, an earlier date belongs to the previous calendar year's fiscal year. Single
364	     * source of truth for the fiscal year, so {@link #getFiscalYear()}, the FY segment of
365	     * the {@link #getMemberId() memberId} and the tenure count in
366	     * {@link #getMembershipPoints()} cannot drift apart.
367	     */
368	    public static int fiscalYearOf(LocalDate date) {
369	        int year = date.getYear();
370	        return date.getMonthValue() >= Month.JULY.getValue() ? year : year - 1;
371	    }
372	
373	    /**
374	     * The owner's fiscal year, formatted {@code "FY<YY>"} where YY is the two-digit FY
375	     * segment of the {@link #getMemberId() memberId} (e.g. {@code "FY26"} for a memberId
376	     * whose FY segment is {@code 26}). Read off the memberId so it cannot drift from the
377	     * identifier; falls back to deriving the fiscal year (starting 1 July) of the
378	     * business-day-adjusted {@link #registrationDate} when no memberId is set. Null when
379	     * neither a memberId nor a registration date is present.
380	     */
381	    @Transient
382	    public String getFiscalYear() {
383	        String base = memberIdBase();
384	        if (base != null && base.length() > MEMBER_ID_SUFFIX_WIDTH) {
385	            int fyStart = base.length() - CHK_WIDTH - HASH8_WIDTH - FY_WIDTH;
386	            return "FY" + base.substring(fyStart, fyStart + FY_WIDTH);
387	        }
388	        if (this.registrationDate == null) {
389	            return null;
390	        }
391	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
392	    }
