394	    /**
395	     * The owner's membership points: a running score built from the owner's own fields.
396	     * Starts at 0 and gains 2 when an email address is present, a further 1 when the owner
397	     * has no namesakes ({@code namesakeCount} is 0), a further 2 when it belongs to a
398	     * household of 3 or more members ({@code householdSize} is 3 or more), and a further 3
399	     * for tenure of more than one elapsed fiscal year (the fiscal years, starting 1 July,
400	     * from {@link #registrationDate} to the current date). A newly created owner has zero
401	     * tenure, so the pre-tenure factors alone top out at 5 points. Derived from the owner's
402	     * own fields.
403	     */
404	    @Transient
405	    public Integer getMembershipPoints() {
406	        int points = 0;
407	        boolean hasEmail = this.email != null && !this.email.isBlank();
408	        if (hasEmail) {
409	            points += 2;
410	        }
411	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
412	        if (unique) {
413	            points += 1;
414	        }
415	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
416	        if (largeHousehold) {
417	            points += 2;
418	        }
419	        boolean tenured = this.registrationDate != null
420	            && (fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate)) > 1;
421	        if (tenured) {
422	            points += 3;
423	        }
424	        return points;
425	    }
426	
427	    /**
428	     * The owner's membership level: a number from 1 to 4 derived by banding
429	     * {@link #getMembershipPoints()} — 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6
430	     * or more. Derived from the owner's own fields, then capped by
431	     * {@link #membershipLevelCap} when set: a new owner's level cannot exceed one above the
432	     * current maximum level among their household members. With no existing household member
433	     * the cap is absent and the banded value stands.
434	     */
435	    @Transient
436	    public Integer getMembershipLevel() {
437	        int level = bandMembershipLevel(getMembershipPoints());
438	        if (this.membershipLevelCap != null && this.membershipLevelCap < level) {
439	            return this.membershipLevelCap;
440	        }
441	        return level;
442	    }
