444	    private static int bandMembershipLevel(int points) {
445	        if (points <= 1) {
446	            return 1;
447	        }
448	        if (points <= 3) {
449	            return 2;
450	        }
451	        if (points <= 5) {
452	            return 3;
453	        }
454	        return 4;
455	    }
