457	    /**
458	     * Fixed city-to-region lookup table. Any city not listed derives locality
459	     * {@code "UNKNOWN"}.
460	     */
461	    private static final Map<String, String> CITY_REGION = Map.of(
462	        "Sydney", "NSW",
463	        "Melbourne", "VIC",
464	        "Brisbane", "QLD");
465	
466	    /**
467	     * Region -> inclusive 4-digit postcode range {low, high}: NSW 2000-2099,
468	     * VIC 3000-3099, QLD 4000-4099. The single source of truth for the
469	     * postcode-to-region mapping, consulted by {@link #regionForPostcode(String)}
470	     * (used by locality derivation) and {@link #hasPostcodeRange(String)} (used by
471	     * postcode validation).
472	     */
473	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
474	        "NSW", new int[] {2000, 2099},
475	        "VIC", new int[] {3000, 3099},
476	        "QLD", new int[] {4000, 4099});
477	
478	    /**
479	     * Fixed region-to-timezone lookup table, mapping each region to its IANA timezone
480	     * name: NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane.
481	     * Any region not listed (including {@code "UNKNOWN"}) has no timezone.
482	     */
483	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
484	        "NSW", "Australia/Sydney",
485	        "VIC", "Australia/Melbourne",
486	        "QLD", "Australia/Brisbane");
487	
488	    /**
489	     * The owner's locality: the REGION component of the owner's region-and-hash identity.
490	     * Read off the leading REGION segment of the {@link #getMemberId() memberId} (the part
491	     * before the fixed-width FY, HASH8 and CHK segments) when a memberId is present,
492	     * otherwise derived straight from the postcode via {@link #identityRegion(String)}.
493	     * Either way this yields the region the memberId was built from — NSW/VIC/QLD, or
494	     * {@code "UNKNOWN"} when the postcode is absent or in no known range. Derived from the
495	     * owner's own fields.
496	     */
497	    @Transient
498	    public String getLocality() {
499	        String base = memberIdBase();
500	        if (base != null && base.length() > MEMBER_ID_SUFFIX_WIDTH) {
501	            return base.substring(0, base.length() - MEMBER_ID_SUFFIX_WIDTH);
502	        }
503	        return identityRegion(this.postcode);
504	    }
505	
506	    /**
507	     * The REGION component of an owner's region-and-hash identity: the region derived from
508	     * the postcode via {@link #regionForPostcode(String)} (NSW/VIC/QLD), or
509	     * {@code "UNKNOWN"} when the postcode is absent or in no known range. The single source
510	     * of truth for the identity's region, so the {@code memberId} REGION segment and the
511	     * {@link #getLocality() locality} cannot drift apart.
512	     */
513	    public static String identityRegion(String postcode) {
514	        String region = regionForPostcode(postcode);
515	        return region != null ? region : "UNKNOWN";
516	    }
517	
518	    /**
519	     * Whether {@code region} is a known region (NSW, VIC or QLD) rather than the
520	     * {@code "UNKNOWN"} sentinel that {@link #identityRegion(String)} yields for a postcode
521	     * in no known range. The single source of truth for "is this a real region?",
522	     * independent of the postcode-range and timezone tables; used by
523	     * {@link #getOwnerSegment() owner segmentation} to decide METRO vs REGIONAL.
524	     */
525	    public static boolean isKnownRegion(String region) {
526	        return !"UNKNOWN".equals(region);
527	    }
528	
529	    /**
530	     * The canonical region for a city per the fixed city-to-region table
531	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), or
532	     * {@code "UNKNOWN"} when the city is not in the table. The single source of truth
533	     * for the city-to-region mapping, used as the city's region in postcode validation.
534	     */
535	    public static String regionForCity(String city) {
536	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
537	    }
538	
539	    /**
540	     * The canonical region for a 4-digit postcode per the fixed range table
541	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code null} when the postcode
542	     * is absent, not a well-formed integer, or in no known range. Reads the shared
543	     * {@link #REGION_POSTCODE_RANGES} table; used by {@link #identityRegion(String)}
544	     * for the identity's region and by postcode validation to range-check a submitted
545	     * postcode against its city's region.
546	     */
547	    public static String regionForPostcode(String postcode) {
548	        if (postcode == null) {
549	            return null;
550	        }
551	        int value;
552	        try {
553	            value = Integer.parseInt(postcode.trim());
554	        } catch (NumberFormatException ex) {
555	            return null;
556	        }
557	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
558	            int[] range = entry.getValue();
559	            if (value >= range[0] && value <= range[1]) {
560	                return entry.getKey();
561	            }
562	        }
563	        return null;
564	    }
565	
566	    /**
567	     * Whether the region is subject to postcode range validation, i.e. has a known
568	     * range in the shared {@link #REGION_POSTCODE_RANGES} table. A region with no range
569	     * (including {@code "UNKNOWN"}) accepts any well-formed postcode.
570	     */
571	    public static boolean hasPostcodeRange(String region) {
572	        return REGION_POSTCODE_RANGES.containsKey(region);
573	    }
574	
575	    /**
576	     * The owner's IANA timezone, derived from the owner's {@link #getLocality() locality}
577	     * (its region) via the fixed region-to-timezone table ({@code NSW->Australia/Sydney},
578	     * {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}). Null when the
579	     * region is not one of these (e.g. {@code "UNKNOWN"}). Derived from the owner's own
580	     * fields.
581	     */
582	    @Transient
583	    public String getTimezone() {
584	        return REGION_TIMEZONE.get(getLocality());
585	    }
586	
587	    /**
588	     * The owner's segment, formatted {@code "<TIER>_<AREA>"} — one of
589	     * {@code "PREMIUM_METRO"}, {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"} or
590	     * {@code "STANDARD_REGIONAL"}. TIER is {@code "PREMIUM"} when
591	     * {@link #getMembershipLevel() membershipLevel} is 3 or more, otherwise
592	     * {@code "STANDARD"}. AREA is {@code "METRO"} when the {@link #getLocality() locality}
593	     * is a known region (NSW, VIC or QLD), otherwise {@code "REGIONAL"}. Derived from the
594	     * owner's own fields.
595	     */
596	    @Transient
597	    public String getOwnerSegment() {
598	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
599	        String area = isKnownRegion(getLocality()) ? "METRO" : "REGIONAL";
600	        return tier + "_" + area;
601	    }
602	
603	    /**
604	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is
605	     * present, otherwise {@code "PHONE"}. Derived from the owner's own fields.
606	     */
607	    @Transient
608	    public String getContactPreference() {
609	        boolean hasEmail = this.email != null && !this.email.isBlank();
610	        return hasEmail ? "EMAIL" : "PHONE";
611	    }
612	
613	    /**
614	     * The owner's identity key: the lower-case hex SHA-256 of
615	     * {@code normalizedTelephone + "|" + lowerEmail + "|" + soundex(lastName)}. The
616	     * telephone is already stored in E.164 form, the email is lower-cased (an empty segment
617	     * when absent), and the last name is reduced to its {@link #soundex(String) Soundex}
618	     * code. This is the single identity used for duplicate detection: two owners with the
619	     * same key are the same person (a 409 on create); an owner whose key differs but whose
620	     * Soundex last name and postcode match an existing owner is a soft match instead.
621	     * Derived from the owner's own fields.
622	     */
623	    @Transient
624	    public String getIdentityKey() {
625	        String normalizedTelephone = keyPart(this.telephone);
626	        String lowerEmail = keyPart(this.email == null ? null : this.email.toLowerCase(Locale.ROOT));
627	        String soundexLastName = soundex(this.getLastName());
628	        return sha256Hex(normalizedTelephone + "|" + lowerEmail + "|" + soundexLastName);
629	    }
630	
631	    private static String keyPart(String value) {
632	        return (value == null || value.isBlank()) ? "" : value;
633	    }
634	
635	    /** Lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
636	    private static String sha256Hex(String value) {
637	        try {
638	            byte[] digest = MessageDigest.getInstance("SHA-256")
639	                .digest(value.getBytes(StandardCharsets.UTF_8));
640	            StringBuilder sb = new StringBuilder(digest.length * 2);
641	            for (byte b : digest) {
642	                sb.append(String.format("%02x", b));
643	            }
644	            return sb.toString();
645	        }
646	        catch (NoSuchAlgorithmException ex) {
647	            throw new IllegalStateException("SHA-256 not available", ex);
648	        }
649	    }
650	
651	    /**
652	     * The American Soundex code of {@code name}: the upper-cased first letter followed by
653	     * three digits that encode the remaining consonants. Vowels and {@code H}/{@code W} are
654	     * not coded; adjacent letters with the same code collapse to one, as do two same-coded
655	     * letters separated only by {@code H} or {@code W}. The code is right-padded with zeros
656	     * and truncated to four characters. An absent or letter-free name yields the empty
657	     * string. The single source of truth for an owner's last-name phonetic key, used by the
658	     * {@link #getIdentityKey() identity key} and by soft-duplicate matching. It lives here
659	     * (rather than beside the exact-match name normalization in the package-private
660	     * {@code OwnerNames} helper) because {@code getIdentityKey()} is an entity-level derived
661	     * getter and must not depend on the request-function layer; the two are distinct name
662	     * concerns — exact comparison vs. phonetic keying — not a duplicated utility.
663	     */
664	    public static String soundex(String name) {
665	        if (name == null) {
666	            return "";
667	        }
668	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
669	        if (letters.isEmpty()) {
670	            return "";
671	        }
672	        StringBuilder code = new StringBuilder();
673	        code.append(letters.charAt(0));
674	        char prev = soundexDigit(letters.charAt(0));
675	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
676	            char c = letters.charAt(i);
677	            char digit = soundexDigit(c);
678	            if (digit != '0' && digit != prev) {
679	                code.append(digit);
680	            }
681	            // Vowels reset the previous code so same-coded consonants either side are coded
682	            // twice; H and W do not, so same-coded letters they separate still collapse.
683	            if (c != 'H' && c != 'W') {
684	                prev = digit;
685	            }
686	        }
687	        while (code.length() < 4) {
688	            code.append('0');
689	        }
690	        return code.toString();
691	    }
692	
693	    private static char soundexDigit(char c) {
694	        switch (c) {
695	            case 'B': case 'F': case 'P': case 'V':
696	                return '1';
697	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
698	                return '2';
699	            case 'D': case 'T':
700	                return '3';
701	            case 'L':
702	                return '4';
703	            case 'M': case 'N':
704	                return '5';
705	            case 'R':
706	                return '6';
707	            default:
708	                return '0';
709	        }
710	    }
711	
712	    /**
713	     * The stored E.164 {@link #telephone} formatted for humans: the country code,
714	     * a space, then the national digits grouped in threes (e.g.
715	     * {@code "+61 412 345 678"}). The {@code '+'} and country code are taken from the
716	     * E.164 value (a {@code '+1'} NANP country code is a single digit, any other is
717	     * treated as two digits, matching the recognized {@code '+61'}/{@code '+1'} forms),
718	     * and the national digits follow in space-separated groups of three. Returns the raw
719	     * value unchanged when it is absent or not a {@code '+'}-prefixed run of digits.
720	     * Derived from the owner's own fields; the raw {@link #telephone} stays E.164.
721	     */
722	    @Transient
723	    public String getTelephoneDisplay() {
724	        if (this.telephone == null || !this.telephone.startsWith("+")) {
725	            return this.telephone;
726	        }
727	        String digits = this.telephone.substring(1);
728	        if (!digits.matches("\\d+")) {
729	            return this.telephone;
730	        }
731	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
732	        if (digits.length() <= countryCodeLength) {
733	            return this.telephone;
734	        }
735	        String countryCode = digits.substring(0, countryCodeLength);
736	        String national = digits.substring(countryCodeLength);
737	        StringBuilder grouped = new StringBuilder();
738	        for (int i = 0; i < national.length(); i += 3) {
739	            if (grouped.length() > 0) {
740	                grouped.append(' ');
741	            }
742	            grouped.append(national, i, Math.min(i + 3, national.length()));
743	        }
744	        return "+" + countryCode + " " + grouped;
745	    }
746	
747	    protected Set<Pet> getPetsInternal() {
748	        if (this.pets == null) {
749	            this.pets = new HashSet<>();
750	        }
751	        return this.pets;
752	    }
753	
754	    protected void setPetsInternal(Set<Pet> pets) {
755	        this.pets = pets;
756	    }
757	
758	    public List<Pet> getPets() {
759	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
760	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
761	        return Collections.unmodifiableList(sortedPets);
762	    }
763	
764	    public void setPets(List<Pet> pets) {
765	        this.pets = new HashSet<>(pets);
766	    }
767	
768	    public void addPet(Pet pet) {
769	        getPetsInternal().add(pet);
770	        pet.setOwner(this);
771	    }
772	
773	    /**
774	     * Return the Pet with the given name, or null if none found for this Owner.
775	     *
776	     * @param name to test
777	     * @return true if pet name is already in use
778	     */
779	    public Pet getPet(String name) {
780	        return getPet(name, false);
781	    }
782	
783	    /**
784	     * Return the Pet with the given name, or null if none found for this Owner.
785	     *
786	     * @param name to test
787	     * @return true if pet name is already in use
788	     */
789	    public Pet getPet(String name, boolean ignoreNew) {
790	        name = name.toLowerCase();
791	        for (Pet pet : getPetsInternal()) {
792	            if (!ignoreNew || !pet.isNew()) {
793	                String compName = pet.getName();
794	                compName = compName.toLowerCase();
795	                if (compName.equals(name)) {
796	                    return pet;
797	                }
798	            }
799	        }
800	        return null;
801	    }
802	
803	    public Pet getPet(Integer petId) {
804	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
805	    }
806	
807	    @Override
808	    public String toString() {
809	        return new ToStringCreator(this)
810	
811	            .append("id", this.getId())
812	            .append("new", this.isNew())
813	            .append("lastName", this.getLastName())
814	            .append("firstName", this.getFirstName())
815	            .append("address", this.address)
816	            .append("city", this.city)
817	            .append("telephone", this.telephone)
818	            .append("email", this.email)
819	            .toString();
820	    }
821	}
